def solve():
    n = 12
    def dfs(seq, used_diffs, used_vals):
        if len(seq) == n:
            return seq

        last = seq[-1]
        for diff in range(1, n):
            if diff not in used_diffs:
                for nxt in (last - diff, last + diff):
                    if 0 <= nxt < n and nxt not in used_vals:
                        used_diffs.add(diff)
                        used_vals.add(nxt)
                        seq.append(nxt)

                        res = dfs(seq, used_diffs, used_vals)
                        if res:
                            return res

                        seq.pop()
                        used_vals.remove(nxt)
                        used_diffs.remove(diff)
        return None

    for start in range(n):
        res = dfs([start], set(), {start})
        if res:
            return res

print(solve())
